from pathlib import Path
from weakref import ref
from pdf_classifier.rust_class_serializer import RustClassSerializer
from pdf_classifier.object import Object
import pytest
import tempfile

# ! generated by AI, asserts that generated file matches original syntax 
# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _make_example_objects() -> list[Object]:
    """
    Mirrors examples/main.py without touching the global OBJECTS list.
    Produces: unknown(0), chapter(1), subchapter(2), diagram(3), datatable(4)
    """
    unknown = Object("unknown", "UNKNOWN_classify", "UNKNOWN_extract")
    chapter = Object("chapter", "classify", "extract", is_organizational=True)
    subchapter = Object("subchapter", "classify", "extract", is_organizational=True)
    diagram = Object("diagram", "classify", "extract")
    datatable = Object("datatable", "classify", "extract")

    # chapter → subchapter
    chapter.children.append(ref(subchapter))
    # subchapter → diagram, datatable
    subchapter.children.append(ref(diagram))
    subchapter.children.append(ref(datatable))
    # diagram ↔ datatable pair
    diagram.pair = (ref(datatable), 1)
    datatable.pair = (ref(diagram), 2)

    return [unknown, chapter, subchapter, diagram, datatable]


def _serializer(objects: list[Object] | None = None) -> RustClassSerializer:
    if objects is None:
        objects = _make_example_objects()
    return RustClassSerializer(objects, Path(tempfile.gettempdir()))


# ---------------------------------------------------------------------------
# Fixtures
# ---------------------------------------------------------------------------

@pytest.fixture
def objs() -> list[Object]:
    return _make_example_objects()


@pytest.fixture
def ser(objs: list[Object]) -> RustClassSerializer:
    return RustClassSerializer(objs, Path(tempfile.gettempdir()))


# ---------------------------------------------------------------------------
# OBJECT_COUNT constant
# ---------------------------------------------------------------------------

class TestObjectCountConst:
    def test_count_matches_object_list_length(self, ser: RustClassSerializer, objs: list[Object]):
        ser._object_count_const()
        assert f"pub const OBJECT_COUNT: u8 = {len(objs)};" in ser.data

    def test_count_value_is_five_for_example_schema(self, ser: RustClassSerializer):
        ser._object_count_const()
        assert "pub const OBJECT_COUNT: u8 = 5;" in ser.data

    def test_single_object_count(self):
        s = RustClassSerializer([Object("unknown", "", "")], Path(tempfile.gettempdir()))
        s._object_count_const()
        assert "pub const OBJECT_COUNT: u8 = 1;" in s.data


