class TestClassEnum:
    def test_enum_declaration_present(self, ser: RustClassSerializer):
        ser._class_enum()
        assert "pub enum KnownObject {" in ser.data

    def test_repr_u8_attribute(self, ser: RustClassSerializer):
        ser._class_enum()
        assert "#[repr(u8)]" in ser.data

    def test_derive_attributes(self, ser: RustClassSerializer):
        ser._class_enum()
        assert "Clone" in ser.data
        assert "Copy" in ser.data
        assert "Debug" in ser.data
        assert "PartialEq" in ser.data
        assert "Eq" in ser.data
        assert "Hash" in ser.data

    def test_all_variants_uppercase(self, ser: RustClassSerializer):
        ser._class_enum()
        for name in ("UNKNOWN", "CHAPTER", "SUBCHAPTER", "DIAGRAM", "DATATABLE"):
            assert name in ser.data

    def test_discriminants_are_sequential(self, ser: RustClassSerializer):
        ser._class_enum()
        # Check each name=index assignment
        for i, name in enumerate(("UNKNOWN", "CHAPTER", "SUBCHAPTER", "DIAGRAM", "DATATABLE")):
            assert f"{name}= {i}" in ser.data


