# ---------------------------------------------------------------------------
# Full generate() — writes to a temp dir and validates file content
# ---------------------------------------------------------------------------

class TestFullGenerate:
    def test_file_is_written(self, objs: list[Object]):
        with tempfile.TemporaryDirectory() as tmp:
            s = RustClassSerializer(objs, Path(tmp))
            s.generate()
            out = Path(tmp) / "generated_object_types.rs"
            assert out.exists()
            assert out.stat().st_size > 0

    def test_generated_content_contains_object_count(self, objs: list[Object]):
        with tempfile.TemporaryDirectory() as tmp:
            s = RustClassSerializer(objs, Path(tmp))
            s.generate()
            content = (Path(tmp) / "generated_object_types.rs").read_text()
            assert "pub const OBJECT_COUNT: u8 = 5;" in content

    def test_generated_content_contains_enum(self, objs: list[Object]):
        with tempfile.TemporaryDirectory() as tmp:
            s = RustClassSerializer(objs, Path(tmp))
            s.generate()
            content = (Path(tmp) / "generated_object_types.rs").read_text()
            assert "pub enum KnownObject {" in content

    def test_generated_content_contains_all_impls(self, objs: list[Object]):
        with tempfile.TemporaryDirectory() as tmp:
            s = RustClassSerializer(objs, Path(tmp))
            s.generate()
            content = (Path(tmp) / "generated_object_types.rs").read_text()
            assert "impl ToString for KnownObject {" in content
            assert "impl TryFrom<&str> for KnownObject {" in content
            assert "impl TryFrom<u8> for KnownObject {" in content
            assert "impl Default for KnownObject {" in content
            assert "impl Into<u8> for KnownObject {" in content

    def test_generated_content_contains_error_enum(self, objs: list[Object]):
        with tempfile.TemporaryDirectory() as tmp:
            s = RustClassSerializer(objs, Path(tmp))
            s.generate()
            content = (Path(tmp) / "generated_object_types.rs").read_text()
            assert "pub enum ObjectCastError {" in content

    def test_data_attribute_populated_after_generate(self, objs: list[Object]):
        with tempfile.TemporaryDirectory() as tmp:
            s = RustClassSerializer(objs, Path(tmp))
            s.generate()
            assert len(s.data) > 0
